-- Hand-written: proposal and estimate versions, status flow, approvals, the freeze trigger recreated and the issue post-condition for versions (M4.3), generated by scripts/write-triggers.ts from src/triggers.ts.
UPDATE documents SET version_group_id = id WHERE type IN ('proposal', 'estimate') AND version_group_id IS NULL AND frozen_at IS NULL;
--> statement-breakpoint
DROP TRIGGER `documents_frozen_update`;
--> statement-breakpoint
CREATE TRIGGER `documents_frozen_update` BEFORE UPDATE ON `documents` WHEN OLD.frozen_at IS NOT NULL AND (
  NEW.`id` IS NOT OLD.`id`
  OR NEW.`type` IS NOT OLD.`type`
  OR NEW.`client_id` IS NOT OLD.`client_id`
  OR NEW.`project_id` IS NOT OLD.`project_id`
  OR NEW.`care_plan_id` IS NOT OLD.`care_plan_id`
  OR NEW.`parent_id` IS NOT OLD.`parent_id`
  OR NEW.`version_group_id` IS NOT OLD.`version_group_id`
  OR NEW.`version` IS NOT OLD.`version`
  OR NEW.`series` IS NOT OLD.`series`
  OR NEW.`fy` IS NOT OLD.`fy`
  OR NEW.`number` IS NOT OLD.`number`
  OR NEW.`number_display` IS NOT OLD.`number_display`
  OR NEW.`currency` IS NOT OLD.`currency`
  OR NEW.`issue_date` IS NOT OLD.`issue_date`
  OR NEW.`due_date` IS NOT OLD.`due_date`
  OR NEW.`valid_until` IS NOT OLD.`valid_until`
  OR NEW.`supply_type` IS NOT OLD.`supply_type`
  OR NEW.`place_of_supply_code` IS NOT OLD.`place_of_supply_code`
  OR NEW.`recipient` IS NOT OLD.`recipient`
  OR NEW.`fx_rate_micros` IS NOT OLD.`fx_rate_micros`
  OR NEW.`fx_date` IS NOT OLD.`fx_date`
  OR NEW.`fx_source` IS NOT OLD.`fx_source`
  OR NEW.`subtotal_minor` IS NOT OLD.`subtotal_minor`
  OR NEW.`discount_minor` IS NOT OLD.`discount_minor`
  OR NEW.`taxable_minor` IS NOT OLD.`taxable_minor`
  OR NEW.`cgst_minor` IS NOT OLD.`cgst_minor`
  OR NEW.`sgst_minor` IS NOT OLD.`sgst_minor`
  OR NEW.`igst_minor` IS NOT OLD.`igst_minor`
  OR NEW.`round_off_minor` IS NOT OLD.`round_off_minor`
  OR NEW.`total_minor` IS NOT OLD.`total_minor`
  OR NEW.`total_inr_minor` IS NOT OLD.`total_inr_minor`
  OR NEW.`terms_version_id` IS NOT OLD.`terms_version_id`
  OR NEW.`snapshot_sha256` IS NOT OLD.`snapshot_sha256`
  OR NEW.`frozen_at` IS NOT OLD.`frozen_at`
  OR NEW.`issued_by` IS NOT OLD.`issued_by`
  OR NEW.`title` IS NOT OLD.`title`
  OR NEW.`contact_id` IS NOT OLD.`contact_id`
  OR NEW.`validity_days` IS NOT OLD.`validity_days`
  OR NEW.`discount_kind` IS NOT OLD.`discount_kind`
  OR NEW.`discount_value` IS NOT OLD.`discount_value`
  OR NEW.`export_mode` IS NOT OLD.`export_mode`
  OR NEW.`content_sha256` IS NOT OLD.`content_sha256`
  OR NEW.`computed` IS NOT OLD.`computed`
  OR NEW.`catalogue_reference_minor` IS NOT OLD.`catalogue_reference_minor`
  OR NEW.`source_document_id` IS NOT OLD.`source_document_id`
  OR NEW.`source_step` IS NOT OLD.`source_step`
  OR NEW.`issuer` IS NOT OLD.`issuer`
  OR NEW.`sent_at` IS NOT OLD.`sent_at`
  OR NEW.`realisation_due_at` IS NOT OLD.`realisation_due_at`
  OR NEW.`created_by` IS NOT OLD.`created_by`
  OR NEW.`created_at` IS NOT OLD.`created_at`
  OR (OLD.`snapshot_r2_key` IS NOT NULL AND NEW.`snapshot_r2_key` IS NOT OLD.`snapshot_r2_key`)
  OR (OLD.`pdf_r2_key` IS NOT NULL AND NEW.`pdf_r2_key` IS NOT OLD.`pdf_r2_key`)
  OR (OLD.`pdf_sha256` IS NOT NULL AND NEW.`pdf_sha256` IS NOT OLD.`pdf_sha256`)
  OR (OLD.`voided_at` IS NOT NULL AND NEW.`voided_at` IS NOT OLD.`voided_at`)
  OR (OLD.`void_reason` IS NOT NULL AND NEW.`void_reason` IS NOT OLD.`void_reason`)
  OR (OLD.`viewed_at` IS NOT NULL AND NEW.`viewed_at` IS NOT OLD.`viewed_at`)
  OR (OLD.`decided_at` IS NOT NULL AND NEW.`decided_at` IS NOT OLD.`decided_at`)
  OR (OLD.`decision_reason` IS NOT NULL AND NEW.`decision_reason` IS NOT OLD.`decision_reason`)
  OR (OLD.`decision_note` IS NOT NULL AND NEW.`decision_note` IS NOT OLD.`decision_note`)
  OR (OLD.`decided_contact_id` IS NOT NULL AND NEW.`decided_contact_id` IS NOT OLD.`decided_contact_id`)
) BEGIN SELECT RAISE(ABORT, 'issued document is frozen'); END;
--> statement-breakpoint
DROP TRIGGER `issue_result_check`;
--> statement-breakpoint
CREATE TRIGGER `issue_result_check` INSTEAD OF INSERT ON `issue_result` WHEN NOT EXISTS (SELECT 1 FROM documents d WHERE d.id = NEW.document_id AND d.status = CASE WHEN d.type IN ('proposal', 'estimate') THEN 'sent' ELSE 'issued' END AND d.frozen_at IS NOT NULL AND d.series = NEW.series AND d.fy = NEW.fy AND d.number >= 1 AND d.number_display IS NOT NULL AND (((d.type NOT IN ('proposal', 'estimate') OR d.version = 1) AND d.number = (SELECT c.next_no - 1 FROM doc_counters c WHERE c.series = NEW.series AND c.fy = NEW.fy)) OR (d.type IN ('proposal', 'estimate') AND d.version > 1 AND EXISTS (SELECT 1 FROM documents v WHERE v.version_group_id = d.version_group_id AND v.version = 1 AND v.frozen_at IS NOT NULL AND v.series = d.series AND v.fy = d.fy AND v.number = d.number AND v.number_display = d.number_display)))) BEGIN SELECT RAISE(ABORT, 'issue did not freeze the document with the number just taken'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_version_insert` BEFORE INSERT ON `documents` WHEN NEW.type IN ('proposal', 'estimate') AND (NEW.version_group_id IS NULL OR (NEW.version = 1 AND NEW.version_group_id IS NOT NEW.id) OR (NEW.version > 1 AND NOT EXISTS (SELECT 1 FROM documents p WHERE p.version_group_id = NEW.version_group_id AND p.version = NEW.version - 1 AND p.frozen_at IS NOT NULL AND p.type = NEW.type AND p.client_id = NEW.client_id AND p.currency = NEW.currency))) BEGIN SELECT RAISE(ABORT, 'documents_version_insert: a proposal or estimate version needs its group, and a later version needs the frozen version before it'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_version_fixed` BEFORE UPDATE OF type, client_id, currency, version_group_id, version ON `documents` WHEN OLD.type IN ('proposal', 'estimate') AND (NEW.type IS NOT OLD.type OR NEW.client_id IS NOT OLD.client_id OR NEW.currency IS NOT OLD.currency OR NEW.version_group_id IS NOT OLD.version_group_id OR NEW.version IS NOT OLD.version) BEGIN SELECT RAISE(ABORT, 'documents_version_fixed: the type, client, currency, group and version of a proposal or estimate never change'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_version_number` BEFORE UPDATE OF number ON `documents` WHEN NEW.type IN ('proposal', 'estimate') AND NEW.version > 1 AND NEW.number IS NOT NULL AND NEW.number IS NOT (SELECT v.number FROM documents v WHERE v.version_group_id = NEW.version_group_id AND v.version = 1) BEGIN SELECT RAISE(ABORT, 'documents_version_number: a later version keeps the number of its first version'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_status_flow` BEFORE UPDATE OF status ON `documents` WHEN NEW.status IS NOT OLD.status AND OLD.type IN ('proposal', 'estimate') AND NOT ((OLD.status = 'draft' AND NEW.status = 'sent') OR (OLD.status = 'sent' AND NEW.status = 'viewed') OR (OLD.status IN ('sent', 'viewed') AND NEW.status IN ('accepted', 'rejected', 'expired', 'revised'))) BEGIN SELECT RAISE(ABORT, 'documents_status_flow: that status change is not allowed'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_contact_scope_insert` BEFORE INSERT ON `documents` WHEN NEW.contact_id IS NOT NULL AND (SELECT client_id FROM contacts WHERE id = NEW.contact_id) IS NOT NEW.client_id BEGIN SELECT RAISE(ABORT, 'documents_contact_scope: the contact must belong to the client'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_contact_scope_update` BEFORE UPDATE OF contact_id, client_id ON `documents` WHEN NEW.contact_id IS NOT NULL AND (SELECT client_id FROM contacts WHERE id = NEW.contact_id) IS NOT NEW.client_id BEGIN SELECT RAISE(ABORT, 'documents_contact_scope: the contact must belong to the client'); END;
--> statement-breakpoint
CREATE TRIGGER `document_lines_catalogue_rate` BEFORE INSERT ON `document_lines` WHEN NEW.catalogue_item_id IS NOT NULL AND NEW.catalogue_rate_minor IS NULL AND (SELECT type FROM documents WHERE id = NEW.document_id) IN ('proposal', 'estimate') BEGIN SELECT RAISE(ABORT, 'document_lines_catalogue_rate: a catalogue line needs its catalogue rate'); END;
--> statement-breakpoint
CREATE TRIGGER `approvals_flow` BEFORE UPDATE ON `approvals` WHEN NEW.kind IS NOT OLD.kind OR NEW.document_id IS NOT OLD.document_id OR NEW.requested_by IS NOT OLD.requested_by OR NEW.content_sha256 IS NOT OLD.content_sha256 OR (NEW.status IS NOT OLD.status AND NOT ((OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected', 'expired')) OR (OLD.status = 'approved' AND NEW.status = 'expired'))) BEGIN SELECT RAISE(ABORT, 'approvals_flow: an approval keeps what it was asked for and only moves forward'); END;
--> statement-breakpoint
CREATE TRIGGER `care_plans_source_fixed` BEFORE UPDATE OF source_document_id ON `care_plans` WHEN OLD.source_document_id IS NOT NULL AND NEW.source_document_id IS NOT OLD.source_document_id BEGIN SELECT RAISE(ABORT, 'care_plans_source_fixed: the source estimate of a care plan is set once'); END;
